insert into public.scenario_screen_translations (screen_id, locale, text) values ('b1000122-0000-0000-0011-000000000122', 'fr', 'S’accroupir devant quelqu’un est intrusif et bizarre. Assieds-toi plutôt à côté d’elle.')
